// Generated by AI (UnitTest MCP)
import { beforeEach, describe, expect, it, vi } from "vitest";

const vscodeMock = vi.hoisted(() => ({
  showErrorMessage: vi.fn(),
  showInformationMessage: vi.fn(),
  showInputBox: vi.fn(),
  showQuickPick: vi.fn(),
  showWarningMessage: vi.fn(),
}));

vi.mock("vscode", () => ({ window: vscodeMock }));

import { TaskAllocationController } from "./taskAllocationController";

function reviewItem(status = "in_review") {
  return {
    task: {
      id: "task:review",
      title: "Review the result",
      status,
    },
  } as never;
}

function controller(callTool = vi.fn()) {
  const refresh = vi.fn(async () => undefined);
  const instance = new TaskAllocationController(
    { isReady: () => true, callTool } as never,
    { isReady: () => true, callTool: vi.fn() } as never,
    {} as never,
    {} as never,
    "session:v1:copilot:test",
    refresh,
    vi.fn()
  );
  return { instance, refresh };
}

describe("TaskAllocationController review actions", () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it("accepts reviewed work with an unverified reviewer label and refreshes", async () => {
    const callTool = vi.fn().mockResolvedValue({ resolved: true });
    const { instance, refresh } = controller(callTool);
    vscodeMock.showInputBox.mockResolvedValue("  Lyndon Swan  ");
    vscodeMock.showWarningMessage.mockResolvedValue("Accept Task");

    await instance.accept(reviewItem());

    expect(vscodeMock.showInputBox).toHaveBeenCalledWith(
      expect.objectContaining({
        prompt: expect.stringContaining("attributed, not authenticated"),
      })
    );
    expect(callTool).toHaveBeenCalledWith("task_transition", {
      task_id: "task:review",
      to: "resolve",
      human: "Lyndon Swan",
    });
    expect(vscodeMock.showInformationMessage).toHaveBeenCalledWith("Accepted Review the result.");
    expect(refresh).toHaveBeenCalledOnce();
  });

  it("returns reviewed work to the claimable pool and refreshes", async () => {
    const callTool = vi.fn().mockResolvedValue({ reopened: true });
    const { instance, refresh } = controller(callTool);
    vscodeMock.showWarningMessage.mockResolvedValue("Retry Task");

    await instance.retry(reviewItem());

    expect(callTool).toHaveBeenCalledWith("task_transition", {
      task_id: "task:review",
      to: "reopen",
    });
    expect(vscodeMock.showInformationMessage).toHaveBeenCalledWith(
      "Returned Review the result to ready work."
    );
    expect(refresh).toHaveBeenCalledOnce();
  });

  it("refuses review actions for a task that is not awaiting review", async () => {
    const callTool = vi.fn();
    const { instance, refresh } = controller(callTool);

    await instance.accept(reviewItem("open"));
    await instance.retry(reviewItem("done"));

    expect(callTool).not.toHaveBeenCalled();
    expect(refresh).not.toHaveBeenCalled();
    expect(vscodeMock.showWarningMessage).toHaveBeenCalledTimes(2);
  });
});
